input.dsl:
workspace "Bank Portal" "C4 model of the online banking platform" {

    !identifiers hierarchical

    model {

        customer = person "Bank Customer" "Uses the platform to manage their accounts, move money, and track their activity"

        bankPortal = softwareSystem "Bank Portal" "Online banking platform owned and operated by our company" {

            webPortal = container "Web Portal" "Web portal where customers log in and manage their accounts"
            mobileAppBackend = container "Mobile App Backend" "Backend that serves the bank's mobile app"
            accountService = container "Account Service" "Holds the customer account records"
            transactionService = container "Transaction Service" "Processes deposits, withdrawals, and transfers"
            paymentService = container "Payment Service" "Executes card payments and bank transfers"
            cardService = container "Card Service" "Manages debit and credit cards"
            fraudDetectionService = container "Fraud Detection Service" "Scores transactions for fraud"
            notificationService = container "Notification Service" "Sends email and SMS alerts"
            onboardingService = container "Onboarding Service" "Verifies new customers"
            statementsService = container "Statements Service" "Generates monthly statements"
            directDebitService = container "Direct Debit Service" "Processes standing orders and direct debits"
            exchangeRatesService = container "Exchange Rates Service" "Provides currency conversion rates"
            batchScheduler = container "Batch Scheduler" "Runs the nightly interest calculation and reconciliation"

            eventQueue = container "Event Queue" {
                description "Carries internal events between the application parts"
                tags "Queue"
            }
            ledgerDb = container "Ledger Database" {
                description "Stores every account movement"
                tags "Database"
            }
            customerDb = container "Customer Database" {
                description "Stores account and profile records"
                tags "Database"
            }
            auditDb = container "Audit Database" {
                description "Stores the compliance audit trail"
                tags "Database"
            }
            cache = container "Cache" {
                description "Stores sessions and frequently read account data"
                tags "Cache"
            }
            documentStore = container "Document Store" {
                description "Holds the generated statement PDFs"
                tags "DocumentStore"
            }
        }

        cardPaymentNetwork = softwareSystem "Card Payment Network" "Card payment network operated by a different organization" "External"
        creditReferenceAgency = softwareSystem "Credit Reference Agency" "Credit reference agency operated by a different organization" "External"

        customer -> bankPortal.webPortal "logs in to manage accounts, move money, and track activity"
        customer -> bankPortal.mobileAppBackend "manages accounts, moves money, and tracks activity via the bank's mobile app"

        bankPortal.webPortal -> bankPortal.accountService "manages accounts through"
        bankPortal.webPortal -> bankPortal.transactionService "submits deposits, withdrawals, and transfers to"
        bankPortal.webPortal -> bankPortal.paymentService "initiates card payments and bank transfers through"
        bankPortal.webPortal -> bankPortal.cardService "manages debit and credit cards through"
        bankPortal.webPortal -> bankPortal.statementsService "requests monthly statements from"
        bankPortal.webPortal -> bankPortal.directDebitService "manages standing orders and direct debits through"

        bankPortal.mobileAppBackend -> bankPortal.accountService "manages accounts through"
        bankPortal.mobileAppBackend -> bankPortal.transactionService "submits deposits, withdrawals, and transfers to"
        bankPortal.mobileAppBackend -> bankPortal.paymentService "initiates card payments and bank transfers through"
        bankPortal.mobileAppBackend -> bankPortal.cardService "manages debit and credit cards through"
        bankPortal.mobileAppBackend -> bankPortal.statementsService "requests monthly statements from"
        bankPortal.mobileAppBackend -> bankPortal.directDebitService "manages standing orders and direct debits through"

        bankPortal.paymentService -> cardPaymentNetwork "routes card authorisations through"
        bankPortal.onboardingService -> creditReferenceAgency "performs credit checks through"

        bankPortal.transactionService -> bankPortal.ledgerDb "updates"
        bankPortal.transactionService -> bankPortal.fraudDetectionService "scores transactions with"
        bankPortal.transactionService -> bankPortal.eventQueue "publishes events to"

        bankPortal.notificationService -> bankPortal.eventQueue "consumes events from"

        bankPortal.statementsService -> bankPortal.ledgerDb "reads"
        bankPortal.statementsService -> bankPortal.documentStore "writes"

        bankPortal.batchScheduler -> bankPortal.ledgerDb "reads and writes"
        bankPortal.batchScheduler -> bankPortal.customerDb "reads and writes"

        bankPortal.paymentService -> bankPortal.cardService "requests card information from"
        bankPortal.paymentService -> bankPortal.exchangeRatesService "requests currency conversion rates from"

        bankPortal.onboardingService -> bankPortal.customerDb "reads"
    }

    views {
        systemContext bankPortal "SystemContext" {
            include *
            autoLayout
            title "System Context for Bank Portal"
        }

        container bankPortal "Containers" {
            include *
            autoLayout
            title "Containers for Bank Portal"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Queue" {
                shape Pipe
            }
            element "Cache" {
                shape Cylinder
            }
            element "DocumentStore" {
                shape Cylinder
            }
        }
    }
}

